package com.dailyhelp.exception;
import java.util.*; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.http.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.core.AuthenticationException; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import jakarta.servlet.http.HttpServletRequest;
@RestControllerAdvice public class ApiExceptionHandler {
 @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<Map<String,Object>> validation(MethodArgumentNotValidException ex,HttpServletRequest req){Map<String,String> errors=new LinkedHashMap<>();ex.getBindingResult().getFieldErrors().forEach(e->errors.putIfAbsent(e.getField(),e.getDefaultMessage()));return response(HttpStatus.BAD_REQUEST,"Validation failed",req,Map.of("fields",errors));}
 @ExceptionHandler(AuthenticationException.class) ResponseEntity<Map<String,Object>> authentication(AuthenticationException ex,HttpServletRequest req){return response(HttpStatus.UNAUTHORIZED,"Invalid email or password",req,Map.of());}
 @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<Map<String,Object>> bad(IllegalArgumentException ex,HttpServletRequest req){return response(HttpStatus.BAD_REQUEST,ex.getMessage(),req,Map.of());}
 @ExceptionHandler(NoSuchElementException.class) ResponseEntity<Map<String,Object>> missing(NoSuchElementException ex,HttpServletRequest req){return response(HttpStatus.NOT_FOUND,"Resource not found",req,Map.of());}
 @ExceptionHandler(DataIntegrityViolationException.class) ResponseEntity<Map<String,Object>> duplicate(DataIntegrityViolationException ex,HttpServletRequest req){return response(HttpStatus.CONFLICT,"A record with those details already exists",req,Map.of());}
 @ExceptionHandler(Exception.class) ResponseEntity<Map<String,Object>> unknown(Exception ex,HttpServletRequest req){return response(HttpStatus.INTERNAL_SERVER_ERROR,"An unexpected error occurred",req,Map.of());}
 private ResponseEntity<Map<String,Object>> response(HttpStatus s,String message,HttpServletRequest r,Map<String,Object> extra){Map<String,Object> b=new LinkedHashMap<>();b.put("status",s.value());b.put("error",s.getReasonPhrase());b.put("message",message);b.put("path",r.getRequestURI());b.putAll(extra);return ResponseEntity.status(s).body(b);}
}